double numeric(const Value&r,const char*k,double fallback=0.){const auto&v=r.get(k).resolved();return(v.kind==Kind::Integer||v.kind==Kind::Number)&&std::isfinite(v.numeric())?v.numeric():fallback;}
double bounded(const Value&r,const char*k,double low,double high,double fallback=0.,int digits=3){return rounded(std::clamp(numeric(r,k,fallback),low,high),digits);}
std::int64_t truncated(const Value&r,const char*k,std::int64_t low,std::int64_t high,std::int64_t fallback=0){return static_cast<std::int64_t>(std::clamp(numeric(r,k,double(fallback)),double(low),double(high)));}
std::string descriptorName(const Value&v,const Value&resources){const auto name=lobby::pythonString(v);if(lobby::truncate(name,96)!=name)return {};auto test=name;test.erase(std::remove_if(test.begin(),test.end(),[](char c){return c==':'||c=='_'||c=='-'||c=='.';}),test.end());return lobby::alnum(test,resources,1000)==test?name:std::string{};}
std::string safeName(const Value&v,const std::string&fallback,const Value&resources){return lobby::safe(v,fallback,resources);}
